const Counter: FunctionComponent<{ onClick: () => void }> = ({
  onClick,
}: {
  onClick: () => void;
}) => {
  const { width, height, y, x } = document
    .querySelector('.bottlesCounterTC')
    .getBoundingClientRect();
  const boxWidth = 271;
  return (
    <div
      className={`${styles.container} ${styles.topRightArrow}`}
      style={{
        width: boxWidth,
        left: Math.floor(x) - boxWidth + width + 18,
        top: y + height + 15,
      }}
    >
      <p
        dangerouslySetInnerHTML={{
          __html: `${getTranslation(
            'ntp_onboarding_bottle_counter'
          )} <img style="width: 18px; vertical-align: bottom;" src="img/bottle-icon-color.svg" alt="" />`,
        }}
      />
      <footer>
        <button style="margin-right: 12px" onClick={onClick}>
          {getTranslation('onboarding_nice')}
        </button>
      </footer>
    </div>
  );
};

