const ComponentsByProp = {
  counter: Counter,
  topSites: TopSites,
  customizeBg: Customize,
  counterFirstBottle: CounterFirstBottle,
  searchForm: SearchForm,
  socialFeed: SocialFeed,
};

const PopoverOnboarding: FunctionComponent<{
  nextStep: string;
  onClick: () => void;
}> = ({ nextStep, onClick }: { nextStep: string; onClick: () => void }) => {
  const Component = ComponentsByProp[nextStep];

  if (!Component) return null;

  return (
    <div className={styles.onboardingPopover}>
      <Component onClick={onClick} />
    </div>
  );
};

export default PopoverOnboarding;
